def has_foreign_around(grid, n, m, cr, cc, size):
    """Check if any foreign 1 touches the diagonal frame"""
    for dr in range(-size - 1, size + 2):
        for dc in range(-size - 1, size + 2):
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < n and 0 <= nc < m:
                # Is this a frame cell?
