    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    d = list(map(int, lines[1].split()))
    h = list(map(int, lines[2].split()))

    # Precompute: prefix sums for heights and distances
    # h[i] is height of tree i (0-indexed)
    pref_h = [0] * n
    pref_h[0] = h[0]
    for i in range(1, n):
        pref_h[i] = pref_h[i - 1] + h[i]

    # pref_dist[i] = sum of distances from tree 0 to tree i (clockwise)
    pref_dist = [0] * n
    pref_dist[0] = 0
    for i in range(1, n):
        pref_dist[i] = pref_dist[i - 1] + d[i - 1]

    # Total circumference (sum of all distances)
    circum = pref_dist[n - 1] + d[n - 1]

    results = []
    for idx in range(m):
        query_line = lines[3 + idx]
        a, b = map(int, query_line.split())
        a -= 1  # Convert to 0-indexed
        b -= 1

        # Mark forbidden trees
        forbidden = set()
        if a <= b:
            for i in range(a, b + 1):
                forbidden.add(i)
        else:
            # Circular range [a, n) U [0, b]
            for i in range(a, n):
                forbidden.add(i)
            for i in range(0, b + 1):
                forbidden.add(i)

        # Get valid trees
        valid = sorted([i for i in range(n) if i not in forbidden])

        if len(valid) < 2:
            continue

        max_energy = 0

        # For each pair of valid trees
        for i in range(len(valid)):
            for j in range(i + 1, len(valid)):
                u, v = valid[i], valid[j]

                # Calculate clockwise distance from u to v
                cw_dist = pref_dist[v] - pref_dist[u]

                # Check if clockwise path crosses forbidden range
                # Forbidden range is [a, b] in sorted order
                # Check if path goes through the forbidden region
                crosses = False
                if a <= b:
                    # Forbidden is [a, b]
                    # Path from u to v crosses if (u < a and v >= a) or (v > b and u <= b)
                    if u < a and v >= a:
                        crosses = True
                    if v > b and u <= b:
                        crosses = True
                    if u <= b and v > b and a < b:
                        crosses = True
                else:
                    # Forbidden wraps: [a, n) U [0, b]
                    # Path crosses if u and v are on opposite sides
                    if (u >= a and v <= b):
                        crosses = True
                    elif (v >= a and u <= b):
                        crosses = True

                if crosses:
                    # Use counter-clockwise distance (go the other way)
                    dist = circum - cw_dist
                else:
                    dist = cw_dist

                energy = 2 * (h[u] + h[v]) + dist
                if energy > max_energy:
                    max_energy = energy

        results.append(str(max_energy))

    return '\n'.join(results)

