def solution(input_data):
    """
    Find minimum operations to transform tree into a star graph.
    The answer is the tree's diameter minus 2.
    """
    lines = input_data.strip().split('\n')
    n = int(lines[0])

    adj = [[] for _ in range(n + 1)]

    for line in lines[1:]:
        if line.strip():
            parts = line.split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)

    # Special case: n <= 2 means no edges, already a star (trivial)
    if n <= 2:
        return "0"

    def bfs(start):
        """BFS to compute distances from start node"""
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = [start]

        while q:
            node = q.pop(0)
            for neighbor in adj[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    q.append(neighbor)

        return dist

    # First BFS from node 1 to find the furthest node
    dist1 = bfs(1)
    max_dist = -1
    furthest_node = 1
    for i in range(1, n + 1):
        if dist1[i] > max_dist:
            max_dist = dist1[i]
            furthest_node = i

    # Second BFS from furthest node to find actual diameter
    full_dist = bfs(furthest_node)
    diameter = 0
    for d in full_dist:
        if d > diameter:
            diameter = d

    # Minimum operations = diameter - 2 (star has diameter 2)
    return str(max(0, diameter - 2))

