import os

def solution(input_str):
    """
    Count triples (A, B, C) in [1, N]³ where:
    1. AB ≠ C (actual equation is false)
    2. d(AB) = d(C) (Billy's digital root check says it's true)

    Where d(x) ≡ x (mod 9), with d(x) = 9 when x % 9 == 0
    """
    n = int(input_str.strip())

    # Digital root pattern in [1, 9]: each value 1-9 appears exactly once in each block of 9
    full_blocks = n // 9
    remainder = n % 9

    # cntD[d] = number of x in [1, n] with digital root d
    cntD = [0] * 10
    for d in range(1, 10):
        cntD[d] = full_blocks + (1 if d <= remainder else 0)

    # f[prod] = number of pairs (A, B) where d(A*B) = prod
    # d(AB) = d(d(A) * d(B))
    f = [0] * 10
    for a in range(1, 10):  # d(A)
        for b in range(1, 10):  # d(B)
            prod = (a * b) % 9
            if prod == 0:
                prod = 9  # digital root is always 1-9
            f[prod] += cntD[a] * cntD[b]

    # Total triples where d(AB) = d(C)
    total = sum(f[d] * cntD[d] for d in range(1, 10))

    # Subtract triples where AB = C (Billy won't make mistake here)
    for c in range(1, n + 1):
        div_count = 0
        for a in range(1, int(c**0.5) + 1):
            if c % a == 0:
                b = c // a
                if a <= n and b <= n:
                    if a == b:
                        div_count += 1
                    else:
                        div_count += 2  # both (a,b) and (b,a)
        total -= div_count

    return str(total) + "\n"

