def solution(input_str):
    MOD = 1000000007

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        clauses.append(parts[1:])

    # Count appearances of each variable
    var_appearances = [0] * (m + 1)
    for clause in clauses:
        for val in clause:
            var_appearances[abs(val)] += 1

    # Union-find to build components
    parent = list(range(m + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Group variables by clause
    var_clauses = [[] for _ in range(m + 1)]
    for idx, clause in enumerate(clauses):
        for val in clause:
            var_clauses[abs(val)].append(idx)

    # Union variables sharing clauses (but each variable appears <= 2 times)
    for var in range(1, m + 1):
        clauses_list = var_clauses[var]
        if len(clauses_list) >= 2:
            first = clauses_list[0]
            for c in clauses_list[1:]:
                # Find all variables in this clause
                for other in range(1, m + 1):
                    if first in var_clauses[other]:
                        union(var, other)

    # BFS to find components
    visited = [False] * (m + 1)
    result = 1

    for i in range(1, m + 1):
        if not visited[i]:
            # Find component using BFS
            component = []
            queue = [i]
            visited[i] = True

            while queue:
                u = queue.pop(0)
                component.append(abs(u) if u != 0 else abs(find(u)))
                comp_val = find(u) if u != 0 else 0

                for v in range(1, m + 1):
                    if find(v) == comp_val and not visited[v]:
                        visited[v] = True
                        queue.append(v)

            component = [abs(u) if u != 0 else 0 for u in component if find(u) == find(abs(i)) or u == 0]

            # Normal component - count variables appearing once
            count_single = sum(1 for v in set(component) if var_appearances[v] <= 1)
            result = (result * pow(2, count_single, MOD)) % MOD

    return str(result) + '\n'
